import json, subprocess
edl = json.loads(open("edl.json", encoding="utf-8").read())
ranges = edl["ranges"]
TRANSITION_BOUNDARIES = [(6, 7), (11, 12), (13, 14), (17, 18), (20, 21)]
trans_a = {a for a,b in TRANSITION_BOUNDARIES}
trans_b = {b for a,b in TRANSITION_BOUNDARIES}
XFADE_DUR = 0.4

def probe(path):
    r = subprocess.run(["ffprobe","-v","error","-show_entries","format=duration","-of","default=nw=1:nk=1",path],capture_output=True,text=True)
    return float(r.stdout.strip())

pos = 0.0
for i,r in enumerate(ranges):
    if i in trans_b:
        continue  # folded into previous transition clip, no separate position
    if i in trans_a:
        # this is start of a transition clip trans_a_b; duration = dur_a+dur_b-XFADE_DUR
        b = dict(TRANSITION_BOUNDARIES)[i]
        pa = probe(f"clips_transitions/trans_{i:02d}_{b:02d}.mp4")
        print(f"range {i} (trans with {b}) starts at {pos:.3f}, clip dur {pa:.3f}")
        if i==18 or b==18:
            print(f"  -> range 18 content starts within this trans clip at local offset = dur_a(seg17)")
            d17 = probe(f"clips_composited/seg_17.mp4")
            print(f"  seg_17 dur={d17:.3f}, so range18 starts at absolute {pos+d17:.3f}")
        pos += pa
    else:
        d = probe(f"clips_composited/seg_{i:02d}.mp4")
        if i==18:
            print(f"range 18 (non-trans) starts at {pos:.3f}, dur {d:.3f}")
        pos += d
EOF
